import { describe, expect, it } from 'vitest';

import { MAX_FIELD_LENGTH, packInt, packString } from '../../src/format/flatpack';
import { FlatPackReader } from '../../src/format/reader';
import { toHex } from '../helpers/bytes';

const encoder = new TextEncoder();

/** Pack then read back a single string field. */
function roundTrip(value: string): void {
  const reader = new FlatPackReader(packString(value));
  expect(reader.readString()).toBe(value);
  expect(reader.atEof()).toBe(true);
}

describe('packString', () => {
  it('prefixes the UTF-8 byte length ("0005hello")', () => {
    expect(toHex(packString('hello'))).toBe('3030303568656c6c6f');
  });

  it('encodes the empty string as "0000"', () => {
    expect(toHex(packString(''))).toBe('30303030');
  });

  it('uses the byte length, not the character count, for multi-byte text', () => {
    const value = 'pässwörd✓';
    const byteLength = encoder.encode(value).length;
    const packed = packString(value);
    expect(packed.length).toBe(4 + byteLength);
    expect(new TextDecoder().decode(packed.subarray(0, 4))).toBe(
      String(byteLength).padStart(4, '0'),
    );
  });

  it('rejects fields longer than 9999 bytes (the format cannot represent them)', () => {
    expect(() => packString('a'.repeat(MAX_FIELD_LENGTH + 1))).toThrow(RangeError);
  });
});

describe('round-trip', () => {
  it('round-trips the empty string', () => {
    roundTrip('');
  });

  it('round-trips "test"', () => {
    roundTrip('test');
  });

  it('round-trips unicode "pässwörd✓"', () => {
    roundTrip('pässwörd✓');
  });

  it('round-trips a long string of exactly 9999 bytes', () => {
    roundTrip('a'.repeat(MAX_FIELD_LENGTH));
  });
});

describe('packInt', () => {
  it('packs an integer as its decimal string', () => {
    expect(toHex(packInt(2))).toBe(toHex(packString('2')));
    expect(packInt(2).length).toBe(5); // "0001" + "2"
  });

  it('round-trips as an int', () => {
    expect(new FlatPackReader(packInt(1234)).readInt()).toBe(1234);
  });
});
